"""Selected fixed-fixture source locations and source-byte hashes, no execution."""
from pathlib import Path
import json,hashlib,re
base=Path.cwd();r=base/'validation/gazebo-joint-closure-v1'
sim=base/'validation/gazebo-source-materials-v1/work/extracted/sim/gz-sim-8.15.0'
phys=base/'validation/gazebo-abi-reassessment-v1/work/extracted/upstream/gz-physics-7.8.0'
dart=base/'validation/gazebo-source-materials-v1/work/extracted/dart/dart-6.13.2'
selected={sim/'src/SimulationRunner.cc':['SimulationRunner::Run(', 'SimulationRunner::UpdateCurrentInfo(', 'SimulationRunner::Step(', 'SimulationRunner::CreateEntities('],sim/'src/SystemManager.cc':['SystemManager::ActivatePendingSystems(', 'SystemManager::AddSystemImpl('],sim/'src/systems/physics/Physics.cc':['PhysicsPrivate::CreatePhysicsEntities(', 'PhysicsPrivate::CreateWorldEntities(', 'PhysicsPrivate::CreateModelEntities(', 'PhysicsPrivate::CreateLinkEntities(', 'PhysicsPrivate::CreateCollisionEntities(', 'PhysicsPrivate::CreateJointEntities(', 'PhysicsPrivate::CreateBatteryEntities(', 'PhysicsPrivate::ResetPhysics(', 'Physics::Update('],phys/'dartsim/src/SDFFeatures.cc':['SDFFeatures::ConstructSdfWorld(', 'SDFFeatures::ConstructSdfModelImpl(', 'SDFFeatures::ConstructSdfLink(', 'SDFFeatures::ConstructSdfCollision(', 'ConstructGeometry('],phys/'dartsim/src/EntityManagementFeatures.cc':['EntityManagementFeatures::ConstructEmptyWorld('],phys/'dartsim/src/Base.hh':['AddWorld(', 'AddModel('],dart/'dart/simulation/World.cpp':['World::World(', 'World::addSkeleton(', 'World::setConstraintSolver(', 'World::step('],dart/'dart/constraint/ConstraintSolver.cpp':['ConstraintSolver::ConstraintSolver(', 'ConstraintSolver::addSkeleton(', 'ConstraintSolver::setCollisionDetector('],dart/'dart/collision/detail/CollisionGroup.hpp':['void CollisionGroup::subscribeTo('],dart/'dart/collision/ode/OdeCollisionDetector.cpp':['OdeCollisionDetector::OdeCollisionDetector(', 'OdeCollisionDetector::collide('],dart/'dart/collision/ode/OdeCollisionGroup.cpp':['OdeCollisionGroup::OdeCollisionGroup('],dart/'dart/collision/fcl/FCLCollisionDetector.cpp':['FCLCollisionDetector::FCLCollisionDetector('],dart/'dart/collision/fcl/FCLCollisionGroup.cpp':['FCLCollisionGroup::FCLCollisionGroup('],dart/'dart/constraint/BoxedLcpConstraintSolver.cpp':['BoxedLcpConstraintSolver::BoxedLcpConstraintSolver('],dart/'dart/dynamics/detail/Skeleton.hpp':['Skeleton::createJointAndBodyNodePair('],dart/'dart/dynamics/Frame.hpp':['getLinearVelocity(', 'getAngularVelocity(']}
rows=[]
for p,terms in selected.items():
 text=p.read_text();locations={term:[text.count('\n',0,m.start())+1 for m in re.finditer(re.escape(term),text)] for term in terms}
 rows.append({'path':str(p.relative_to(base)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'locations':locations})
(r/'reports/call_path_locations.json').write_text(json.dumps(rows,indent=2)+'\n')
print('source location records',len(rows),'missing symbols',[(x['path'],k) for x in rows for k,v in x['locations'].items() if not v])
